        <script type='text/javascript'>
            var isCtrl = false;
            document.onkeyup = function(e)
            {
// alert('here'+e.which);
                if (e.which == 17)
                    isCtrl = false;
            }
            document.onkeydown = function(e)
            {
                if (e.which == 123)
                    isCtrl = true;
                if (((e.which == 85) || (e.which == 65) || (e.which == 88) || (e.which == 67) || (e.which == 86) || (e.which == 2) || (e.which == 3) || (e.which == 123) || (e.which == 83)) && isCtrl == true)
                {
                    //alert('This is Function Disabled');
                    return false;
                }
            }
// right click code
            var isNS = (navigator.appName == "Netscape") ? 1 : 0;
            if (navigator.appName == "Netscape")
                document.captureEvents(Event.MOUSEDOWN || Event.MOUSEUP);
            function mischandler() {
                //alert('This is Function Disabled');
                return false;
            }
            function mousehandler(e) {
                var myevent = (isNS) ? e : event;
                var eventbutton = (isNS) ? myevent.which : myevent.button;
                if ((eventbutton == 2) || (eventbutton == 3))
                    return false;
            }
            document.oncontextmenu = mischandler;
            document.onmousedown = mousehandler;
            document.onmouseup = mousehandler;
//select content code disable  alok goyal
            function killCopy(e) {
                return false
            }
            function reEnable() {
                return true
            }
            document.onselectstart = new Function("return false")
            if (window.sidebar) {
                document.onmousedown = killCopy
                document.onclick = reEnable
            }
        </script>

        <script type="text/javascript">
            function fnFilterColumn(i, txtVal)
            {
                $('#tbl_data').dataTable().fnFilter(
                        txtVal,
                        i,
                        true,
                        true
                        );
            }


            $(document).ready(function()
            {
                $('#tbl_data').dataTable();
                reloadStylesheets();

                $('a.chFilter').click(function(event)
                {
                    event.preventDefault();
                    if ($(this).text() == 'क्ष')
                        fnFilterColumn(2, '(^[क्ष])');
                    else if ($(this).text() == 'त्र')
                        fnFilterColumn(2, '(^[त्र])');
                    else if($(this).text() == 'ज्ञ')
                        fnFilterColumn(2, '(^[ज्ञ])');
                    else if ($(this).text() != 'All')
                        fnFilterColumn(2, '(^[' + $(this).text() + '])');
                    else
                        fnFilterColumn(2, '');
                });



                $(document).on('click', 'button.btnData', function()
                {
                    $('#frmSubmit').append('<input type="hidden" name="hidData" value="' + $(this).attr('name') + '">');
                    $('#frmSubmit').appendTo($('body'));
                    $('#frmSubmit').submit();
                });
            });

        </script>
